const i=(r,a)=>{const o=Math.floor(r/86400),e=Math.floor(r%86400/3600),n=Math.floor(r%3600/60),S=r%60;let t="";return o>0&&(t=`${o.toString().padStart(2,"0")}`,t+=a?"天":":"),(e>0||o>0&&e==0)&&(t+=`${e.toString().padStart(2,"0")}`,t+=a?"时":":"),n>=0&&(t+=`${n.toString().padStart(2,"0")}`,t+=a?"分":":"),S>=0&&(t+=`${S.toString().padStart(2,"0")}`,t+=a?"秒":""),t||"00:00:00"},s=r=>{const a=new Date(r*1e3),o=a.getFullYear(),e=(a.getMonth()+1).toString().padStart(2,"0"),n=a.getDate().toString().padStart(2,"0");return`${o}-${e}-${n}`};export{s as a,i as f};
